public class CompositeShardRouter {
    private final int totalShards;

    public CompositeShardRouter(int totalShards) {
        this.totalShards = totalShards;
    }

    public int resolveShard(String tenantId, String entityId) {
        // Salt the hash calculation with the tenantId to prevent hotspots
        // caused by sequential entity IDs within a single high-volume tenant.
        String compositeKey = tenantId + "#" + entityId;
        int hash = Math.abs(compositeKey.hashCode());
        return hash % totalShards;
    }
}
